import sys, json

# Handle potentially concatenated JSON by reading first complete object
text = sys.stdin.read()
# Find the matching end of first JSON object
depth = 0
end = 0
for i, c in enumerate(text):
    if c == '{': depth += 1
    elif c == '}': 
        depth -= 1
        if depth == 0:
            end = i + 1
            break

data = json.loads(text[:end])
for proj in data.get('projects', []):
    name = proj['path'].split('/')[-1]
